page('index.html', 'مكتب أوش — الرئيسية', 'جناح إنتاج متكامل داخل دليل المصادر المفتوحة: مستندات وجداول بيانات وعروض تقديمية ومهام، محلي بالكامل ومدعوم بذكاء المنصة.', hub_body, '<script type="module" src="./js/hub.js"></script>', '')

